css:
@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@keyframes grid-move {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: 30px 30px;
  }
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

/* Component Styles */
.nhost-card {
  --bg-color: #0c111d;
  --card-border: #1f2937;
  --text-primary: #f3f4f6;
  --text-secondary: #9ca3af;
  --accent-color: #0052cc;
  --accent-glow: rgba(0, 82, 204, 0.35);
  --brand-gradient: linear-gradient(135deg, #0052cc, #2684ff);

  font-family: "Inter", system-ui, sans-serif;
  width: 100%;
  max-width: 400px;
  background-color: var(--bg-color);
  border: 1px solid var(--card-border);
  border-radius: 16px;
  padding: 24px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 4px 24px -1px rgba(0, 0, 0, 0.2);
  transition:
    transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
    box-shadow 0.3s ease,
    border-color 0.3s ease;
  z-index: 1;
}

.nhost-card:hover {
  transform: translateY(-4px) scale(1.01);
  box-shadow:
    0 20px 40px -5px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(38, 132, 255, 0.3);
  border-color: rgba(38, 132, 255, 0.5);
}

.card-grid {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: linear-gradient(
      rgba(255, 255, 255, 0.05) 1px,
      transparent 1px
    ),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 30px 30px;
  mask-image: linear-gradient(to bottom, black 40%, transparent 100%);
  pointer-events: none;
  z-index: -2;
  transition: opacity 0.5s ease;
  opacity: 0.5;
}

.nhost-card:hover .card-grid {
  animation: grid-move 20s linear infinite;
  opacity: 0.8;
}

.card-glow {
  position: absolute;
  top: -50px;
  right: -50px;
  width: 150px;
  height: 150px;
  background: radial-gradient(
    circle,
    var(--accent-glow) 0%,
    rgba(0, 0, 0, 0) 70%
  );
  filter: blur(40px);
  z-index: -1;
  transition: all 0.5s ease;
}

.nhost-card:hover .card-glow {
  transform: scale(1.5);
  background: radial-gradient(
    circle,
    rgba(38, 132, 255, 0.4) 0%,
    rgba(0, 0, 0, 0) 70%
  );
}

/* Header Section */
.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.brand-wrapper {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo-container {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.03);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: background 0.3s ease;
}

.nhost-logo {
  width: 24px;
  height: 24px;
  color: #fff;
  filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.3));
}

.brand-text {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--text-primary);
}

/* Actions */
.action-buttons {
  display: flex;
  gap: 8px;
}

.btn-icon {
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
  color: var(--text-secondary);
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-icon:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  transform: translateY(-2px);
}

.icon {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

.icon.star {
  transition: color 0.2s;
}

.btn-icon:hover .icon.star {
  color: #fbbf24;
  filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.5));
}

/* Body Section */
.card-body {
  position: relative;
}

.repo-title {
  font-family: "JetBrains Mono", monospace;
  font-size: 24px;
  font-weight: 500;
  color: var(--text-primary);
  margin: 0 0 12px 0;
  display: flex;
  align-items: center;
}

.blinking-cursor {
  display: inline-block;
  width: 10px;
  height: 3px;
  background-color: var(--accent-color);
  margin-left: 6px;
  animation: blink 1s step-end infinite;
  box-shadow: 0 0 8px var(--accent-color);
}

.repo-description {
  font-size: 15px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 0 0 24px 0;
}

/* Tags */
.tag-wrapper {
  display: flex;
  gap: 10px;
}

.badge {
  font-family: "JetBrains Mono", monospace;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
  transition: all 0.3s ease;
  cursor: default;
  position: relative;
  overflow: hidden;
}

/* JS Tag */
.badge-js {
  background-color: rgba(247, 223, 30, 0.1);
  color: #f7df1e;
  border: 1px solid rgba(247, 223, 30, 0.2);
}

.badge-js:hover {
  background-color: rgba(247, 223, 30, 0.2);
  box-shadow: 0 0 12px rgba(247, 223, 30, 0.2);
  transform: translateY(-1px);
}

/* TS Tag */
.badge-ts {
  background-color: rgba(49, 120, 198, 0.1);
  color: #3178c6;
  border: 1px solid rgba(49, 120, 198, 0.2);
}

.badge-ts:hover {
  background-color: rgba(49, 120, 198, 0.2);
  box-shadow: 0 0 12px rgba(49, 120, 198, 0.3);
  transform: translateY(-1px);
}
